//! celestia-app v3.13.0's interface registry and message schema (app
//! version 1, cosmos-sdk v0.46, ibc-go v6), generated by
//! `conformance/v1-oracle -registry-out` from the registry Go builds in
//! `encoding.MakeConfig(app.ModuleEncodingRegisters...)`.
//!
//! [`decode_v1`](crate::decode_v1) decodes with these tables instead of
//! v10's: a type URL outside [`TYPE_URLS_V1`] does not resolve, and every
//! message decodes with its v0.46 fields ([`MESSAGES_V1`]), so a field a
//! later release added is unknown.

use celestia_proto::wire_table::{FieldInfo, MessageInfo};

use crate::registry::iface;

use MessageInfo as M;

/// [`celestia_proto::wire_table`]'s compact field constructor. `flags`:
/// bit 0 repeated, 1 packed, 2 stdtime, 3 stdduration, 4 nullable.
const fn f(
    number: u32,
    ty: u8,
    flags: u8,
    oneof: i32,
    type_name: &'static str,
    custom: &'static str,
) -> FieldInfo {
    FieldInfo {
        number,
        ty,
        repeated: flags & 1 != 0,
        packed: flags & 2 != 0,
        type_name,
        custom,
        std_time: flags & 4 != 0,
        std_duration: flags & 8 != 0,
        nullable: flags & 16 != 0,
        oneof,
    }
}

include!("wire_table_v1.rs");
include!("registry_table_v1.rs");

/// The v0.46 schema of message `name` (full name, no leading dot).
pub(crate) fn message(name: &str) -> Option<&'static MessageInfo> {
    MESSAGES_V1
        .binary_search_by(|m| m.name.cmp(name))
        .ok()
        .map(|i| &MESSAGES_V1[i])
}

/// The v1 registry entry of `type_url`.
pub(crate) fn lookup(type_url: &[u8]) -> Option<&'static (&'static str, &'static str, u32)> {
    TYPE_URLS_V1
        .binary_search_by(|(u, _, _)| u.as_bytes().cmp(type_url))
        .ok()
        .map(|i| &TYPE_URLS_V1[i])
}

/// Whether `iface` has a registered implementation in the v1 registry.
pub(crate) fn has_impls(iface: u32) -> bool {
    TYPE_URLS_V1.iter().any(|(_, _, bits)| bits & iface != 0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_and_closed() {
        assert!(MESSAGES_V1.windows(2).all(|w| w[0].name < w[1].name));
        assert!(TYPE_URLS_V1.windows(2).all(|w| w[0].0 < w[1].0));
        for (url, name, _) in TYPE_URLS_V1 {
            assert!(message(name).is_some(), "{url} -> {name} has no schema");
        }
        for m in MESSAGES_V1 {
            for fi in m.fields {
                if fi.ty == celestia_proto::wire_table::ty::MESSAGE {
                    assert!(
                        message(fi.type_name).is_some(),
                        "{}: {}",
                        m.name,
                        fi.type_name
                    );
                }
            }
        }
        // v1 knows blobstream's message and no later ones.
        let qgb = lookup(b"/celestia.qgb.v1.MsgRegisterEVMAddress").unwrap();
        assert_eq!(qgb.2, iface::MSG);
        assert!(lookup(b"/celestia.signal.v1.MsgSignalVersion").is_some());
        assert!(lookup(b"/cosmos.bank.v1beta1.MsgUpdateParams").is_none());
        // v0.46's SendAuthorization has no allow list (field 2).
        let send = message("cosmos.bank.v1beta1.SendAuthorization").unwrap();
        assert!(send.field(1).is_some() && send.field(2).is_none());
        assert!(has_impls(iface::HEADER) && !has_impls(iface::CLIENT_MESSAGE));
    }
}
